import React, { useState } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import ErrorModal from '../common/ErrorModal';
import SuccessModal from '../common/SuccessModal';

interface QuartoFormData {
  numero: string;
  diaria: string;
}

interface FormErrors {
  numero?: string;
  diaria?: string;
}

const CadastrarQuarto: React.FC = () => {
  const { theme } = useTheme();

  const [formData, setFormData] = useState<QuartoFormData>({
    numero: '',
    diaria: ''
  });
  const [errors, setErrors] = useState<FormErrors>({});
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isCheckingNumero, setIsCheckingNumero] = useState<boolean>(false);
  const [numeroExistente, setNumeroExistente] = useState<boolean>(false);
  
  // Estados para o modal de erro
  const [isErrorModalOpen, setIsErrorModalOpen] = useState<boolean>(false);
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [errorDetails, setErrorDetails] = useState<string>('');
  
  // Estados para o modal de sucesso
  const [isSuccessModalOpen, setIsSuccessModalOpen] = useState<boolean>(false);
  const [successTitle, setSuccessTitle] = useState<string>('');
  const [successMessage, setSuccessMessage] = useState<string>('');
  const [successDetails, setSuccessDetails] = useState<string>('');

  const validateForm = (): boolean => {
    const newErrors: FormErrors = {};

    // Validar número
    if (!formData.numero.trim()) {
      newErrors.numero = 'Número do quarto é obrigatório';
    } else {
      const numero = parseInt(formData.numero);
      const andar = Math.floor(numero / 100);
      const numeroNoAndar = numero % 100;
      
      if (isNaN(numero) || andar < 1 || andar > 5 || numeroNoAndar < 0 || numeroNoAndar > 20) {
        newErrors.numero = 'Número inválido. Use o formato: 100-120 (1º andar), 200-220 (2º andar), ..., 500-520 (5º andar)';
      }
    }

    // Validar diária
    if (!formData.diaria.trim()) {
      newErrors.diaria = 'Diária é obrigatória';
    } else {
      // Remover formatação para converter para número
      const diariaNumerica = parseInt(formData.diaria.replace(/[^\d]/g, ''));
      if (isNaN(diariaNumerica) || diariaNumerica <= 0) {
        newErrors.diaria = 'Diária deve ser um valor positivo';
      } else if (diariaNumerica < 550) {
        newErrors.diaria = 'Diária mínima é R$ 550,00';
      } else if (diariaNumerica > 10000) {
        newErrors.diaria = 'Diária máxima é R$ 10.000,00';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const showErrorModal = (message: string, details?: string) => {
    setErrorMessage(message);
    setErrorDetails(details || '');
    setIsErrorModalOpen(true);
  };

  const closeErrorModal = () => {
    setIsErrorModalOpen(false);
    setErrorMessage('');
    setErrorDetails('');
  };

  const showSuccessModal = (title: string, message: string, details?: string) => {
    setSuccessTitle(title);
    setSuccessMessage(message);
    setSuccessDetails(details || '');
    setIsSuccessModalOpen(true);
  };

  const closeSuccessModal = () => {
    setIsSuccessModalOpen(false);
    setSuccessTitle('');
    setSuccessMessage('');
    setSuccessDetails('');
  };

  // Formatar diária como moeda brasileira
  const formatDiaria = (value: string) => {
    // Remove tudo que não é dígito
    let numeros = value.replace(/[^\d]/g, '');
    
    // Converte para número e divide por 100 para tratar centavos
    let valor = parseInt(numeros) / 100;
    
    if (isNaN(valor)) valor = 0;
    
    // Formata como moeda brasileira
    return valor.toLocaleString('pt-BR', {
      style: 'currency',
      currency: 'BRL',
      minimumFractionDigits: 2
    });
  };

  // Verificar se número já existe via API
  const verificarNumeroExistente = async (numero: string) => {
    if (!numero) {
      setNumeroExistente(false);
      return;
    }

    const numeroInt = parseInt(numero);
    if (isNaN(numeroInt)) {
      setNumeroExistente(false);
      return;
    }

    setIsCheckingNumero(true);
    try {
      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';
      const token = localStorage.getItem('token');
      
      console.log('Verificando número:', numeroInt, 'URL:', `${API_BASE_URL}/quartos/numero/${numeroInt}`);
      
      const response = await fetch(`${API_BASE_URL}/quartos/numero/${numeroInt}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': token ? `Bearer ${token}` : ''
        }
      });

      console.log('Resposta da verificação:', response.status);

      if (response.ok) {
        // Se retornar 200, o quarto existe
        setNumeroExistente(true);
        setErrors((prev: FormErrors) => ({ ...prev, numero: 'Este quarto já está cadastrado' }));
      } else if (response.status === 404) {
        // Se retornar 404, o quarto não existe
        setNumeroExistente(false);
        setErrors((prev: FormErrors) => ({ ...prev, numero: '' }));
      } else {
        // Outros erros
        console.error('Erro inesperado na verificação:', response.status, response.statusText);
        throw new Error(`Erro ${response.status}: ${response.statusText}`);
      }
    } catch (error) {
      console.error('Erro ao verificar número:', error);
      // Se der erro na verificação, assume que não existe para não bloquear
      setNumeroExistente(false);
      setErrors((prev: FormErrors) => ({ 
        ...prev, 
        numero: 'Não foi possível verificar o número. Tente novamente.' 
      }));
    } finally {
      setIsCheckingNumero(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    
    let processedValue = value;
    
    if (name === 'numero') {
      // Apenas números
      processedValue = value.replace(/\D/g, '');
      
      // Verificar se número já existe (com debounce)
      setTimeout(() => {
        verificarNumeroExistente(processedValue);
      }, 500);
    } else if (name === 'diaria') {
      // Aplicar máscara de moeda
      processedValue = formatDiaria(value);
    }
    
    setFormData((prev: QuartoFormData) => ({
      ...prev,
      [name]: processedValue
    }));
    
    // Clear error for this field when user starts typing
    if (errors[name as keyof FormErrors]) {
      setErrors((prev: FormErrors) => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    if (numeroExistente) {
      showErrorModal('Quarto já existe', 'Este número de quarto já está cadastrado no sistema. Escolha outro número.');
      return;
    }

    setIsLoading(true);

    try {
      // Preparar dados para a API
      const quartoData = {
        numero: parseInt(formData.numero),
        diaria: parseInt(formData.diaria.replace(/[^\d]/g, '')) // Remove formatação e converte para integer
      };

      console.log('Dados enviados para API:', quartoData);

      // Enviar para a API
      const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';
      const token = localStorage.getItem('token');
      
      const response = await fetch(`${API_BASE_URL}/quartos`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': token ? `Bearer ${token}` : ''
        },
        body: JSON.stringify(quartoData)
      });

      if (response.ok) {
        const result = await response.json();
        
        // Mostrar modal de sucesso
        showSuccessModal(
          'Quarto Cadastrado!',
          `O quarto ${formData.numero} foi cadastrado com sucesso.`,
          `Diária: R$ ${formData.diaria} | Status: Disponível`
        );
        
        // Reset form
        setFormData({
          numero: '',
          diaria: ''
        });
        setNumeroExistente(false);
        setErrors({});
      } else {
        const errorData = await response.json().catch(() => ({}));
        throw new Error((errorData as any).message || `Erro ${response.status}`);
      }
      
    } catch (error: any) {
      console.error('Erro ao cadastrar quarto:', error);
      
      let errorMessage = 'Erro ao cadastrar quarto. Tente novamente.';
      let errorDetails = '';
      
      if (error.message.includes('409')) {
        errorMessage = 'Número de quarto já existe';
        errorDetails = 'Este número de quarto já está cadastrado no sistema.';
      } else if (error.message.includes('400')) {
        errorMessage = 'Dados inválidos';
        errorDetails = 'Verifique os campos e tente novamente.';
      } else if (error.message.includes('401')) {
        errorMessage = 'Não autorizado';
        errorDetails = 'Faça login novamente para continuar.';
      } else if (error.message.includes('500')) {
        errorMessage = 'Erro no servidor';
        errorDetails = 'Tente novamente mais tarde.';
      } else if (error.message.includes('Failed to fetch')) {
        errorMessage = 'Erro de conexão';
        errorDetails = 'Não foi possível conectar ao servidor. Verifique sua internet.';
      }
      
      showErrorModal(errorMessage, errorDetails);
      
    } finally {
      setIsLoading(false);
    }
  };

  const handleLimpar = () => {
    setFormData({
      numero: '',
      diaria: ''
    });
    setErrors({});
    setNumeroExistente(false);
  };

  return (
    <div className="max-w-2xl mx-auto p-6">
      <div className="card">
        <div className="mb-6">
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Cadastrar Quarto</h2>
          <p className="mt-1 text-sm text-gray-600 dark:text-gray-400">
            Preencha os dados do novo quarto
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Número do Quarto */}
            <div>
              <label htmlFor="numero" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Número do Quarto *
              </label>
              <input
                type="text"
                id="numero"
                name="numero"
                value={formData.numero}
                onChange={handleInputChange}
                placeholder="Ex: 101, 205, 315"
                className={`input-field ${errors.numero || numeroExistente ? 'border-red-300 dark:border-red-700' : ''}`}
                disabled={isLoading}
                maxLength={3}
              />
              {errors.numero && (
                <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.numero}</p>
              )}
              {isCheckingNumero && (
                <p className="mt-1 text-sm text-blue-600 dark:text-blue-400">Verificando número...</p>
              )}
            </div>

            {/* Diária */}
            <div>
              <label htmlFor="diaria" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Diária (R$) *
              </label>
              <input
                type="text"
                id="diaria"
                name="diaria"
                value={formData.diaria}
                onChange={handleInputChange}
                placeholder="R$ 0,00"
                className={`input-field ${errors.diaria ? 'border-red-300 dark:border-red-700' : ''}`}
                disabled={isLoading}
              />
              {errors.diaria && (
                <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.diaria}</p>
              )}
            </div>
          </div>

          {/* Informações sobre os quartos */}
          <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
            <h4 className="text-sm font-medium text-blue-800 dark:text-blue-200 mb-2">
              📋 Informações sobre os Quartos
            </h4>
            <ul className="text-xs text-blue-600 dark:text-blue-400 space-y-1">
              <li>• 5 andares disponíveis (1º ao 5º)</li>
              <li>• 21 quartos por andar:</li>
              <li> - 1º andar: 100 a 120</li>
              <li> - 2º andar: 200 a 220</li>
              <li> - 3º andar: 300 a 320</li>
              <li> - 4º andar: 400 a 420</li>
              <li> - 5º andar: 500 a 520</li>
              <li>• Total: 105 quartos disponíveis</li>
              <li>• Diária mínima: R$ 550,00</li>
              <li>• Todo quarto cadastrado fica com status "Disponível"</li>
              <li>• Números repetidos não são permitidos</li>
            </ul>
          </div>

          {/* Botões */}
          <div className="flex flex-col sm:flex-row gap-3 justify-end">
            <button
              type="button"
              onClick={handleLimpar}
              className="btn-secondary"
              disabled={isLoading}
            >
              Limpar
            </button>
            <button
              type="submit"
              className="btn-primary"
              disabled={isLoading || numeroExistente}
            >
              {isLoading ? (
                <>
                  <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Cadastrando...
                </>
              ) : (
                'Cadastrar Quarto'
              )}
            </button>
          </div>
        </form>
      </div>

      {/* Modal de Erro */}
      <ErrorModal
        isOpen={isErrorModalOpen}
        onClose={closeErrorModal}
        title="Erro ao Cadastrar Quarto"
        message={errorMessage}
        details={errorDetails}
      />

      {/* Modal de Sucesso */}
      <SuccessModal
        isOpen={isSuccessModalOpen}
        onClose={closeSuccessModal}
        title={successTitle}
        message={successMessage}
        details={successDetails}
      />
    </div>
  );
};

export default CadastrarQuarto;
